1	/**
2	 * Prisma is loaded ON DEMAND rather than at module scope.
3	 *
4	 * Everything in this file except `renderTemplate` and `recordEmail` is pure
5	 * string composition, and those two are the only lines that need a database. A
6	 * top-level `import { db }` made the whole module — and therefore
7	 * `lib/email-templates.ts`, which imports it — construct a `PrismaClient` merely
8	 * to build an HTML string, which in turn made the rendering logic untestable:
9	 * importing it from a unit test would point Prisma at the PRODUCTION
10	 * `DATABASE_URL` in /opt/nxeon/.env. The redaction below is a security control,
11	 * so it must be testable without that. Dynamic import keeps the module
12	 * dependency-free until a function that genuinely needs a row is called.
13	 */
14	async function prisma() {
15	  return (await import("@/lib/db")).db;
16	}
17	
18	/**
19	 * DB-backed email rendering + the shared branded email shell.
20	 *
21	 * Templates live in the `EmailTemplate` table (admin-editable). Each row stores
22	 * a `subject` and an HTML *body* containing `{{variable}}` placeholders. At send
23	 * time we load the row, substitute the variables, and wrap the body in the
24	 * shared branded shell (header/footer). If a template is missing or disabled we
25	 * fall back to a minimal built-in default so a send never silently produces an
26	 * empty email.
27	 *
28	 * DESIGN (2026 refresh): a light, deliverability-safe theme. Real-world inbox
29	 * data shows light emails land in the primary tab more reliably than dark ones,
30	 * so the body is a soft violet-tinted background with a white content card and a
31	 * violet accent header carrying the Nxeon wordmark. Everything is table-based
32	 * with fully inline styles — Gmail/Outlook/Apple-Mail strip <style>, flexbox and
33	 * external CSS, so none of those are used. Gradients degrade to a solid
34	 * `background-color` fallback in clients that drop `background-image`.
35	 *
36	 * This module has NO dependency on `lib/mailer.ts` (mailer depends on it), which
37	 * keeps the import graph acyclic.
38	 */
39	
40	/** Brand palette — violet primary (#8a70fb / #6f47f5) on a light, navy-ink card. */
41	export const BRAND = {
42	  // Header / primary accent
43	  violet: "#6f47f5",
44	  violetLight: "#8a70fb",
45	  violetDeep: "#5f2ee8",
46	  // Surfaces
47	  pageBg: "#eef0f8",
48	  card: "#ffffff",
49	  panel: "#f6f5fd",
50	  panelBorder: "#e7e3f7",
51	  hair: "#ecebf3",
52	  // Ink
53	  ink: "#1c1638",
54	  body: "#4a4763",
55	  muted: "#8a86a3",
56	  faint: "#a7a4bd",
57	  // Status
58	  success: "#15a34a",
59	  successBg: "#e9f8ef",
60	  warn: "#c2790b",
61	  warnBg: "#fdf3e3",
62	  danger: "#dc2626",
63	  dangerBg: "#fdecec",
64	  info: "#6f47f5",
65	  infoBg: "#f1edfe",
66	};
67	const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
68	
69	export function appUrl(): string {
70	  return process.env.APP_URL ?? "https://nxeon.cloud";
71	}
72	
73	const esc = (s: unknown) =>
74	  String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
75	
76	// ---------------------------------------------------------------------------
77	// Reusable, fully-inline email components. Every template composes these so the
78	// look stays consistent. All return an HTML string.
79	// ---------------------------------------------------------------------------
80	
81	export type Accent = "violet" | "success" | "warn" | "danger" | "info";
82	const accentColor = (a: Accent = "violet") =>
83	  a === "success" ? BRAND.success : a === "warn" ? BRAND.warn : a === "danger" ? BRAND.danger : BRAND.violet;
84	const accentBg = (a: Accent = "violet") =>
85	  a === "success" ? BRAND.successBg : a === "warn" ? BRAND.warnBg : a === "danger" ? BRAND.dangerBg : BRAND.infoBg;
86	
87	/** Small uppercase eyebrow/kicker label above the headline. */
88	export function emailEyebrow(text: string, accent: Accent = "violet"): string {
89	  return `<div style="margin:0 0 12px;font-family:${FONT};font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:${accentColor(accent)};">${esc(text)}</div>`;
90	}
91	
92	/** Main headline. */
93	export function emailHeading(text: string): string {
94	  return `<h1 style="margin:0 0 14px;font-family:${FONT};font-size:23px;line-height:1.3;font-weight:700;color:${BRAND.ink};">${esc(text)}</h1>`;
95	}
96	
97	/** Body paragraph. `html` may contain trusted inline markup (links, <b>). */
98	export function emailParagraph(html: string): string {
99	  return `<p style="margin:0 0 16px;font-family:${FONT};font-size:15px;line-height:1.65;color:${BRAND.body};">${html}</p>`;
100	}
101	
102	/** Small muted note (fine print, alternate-link fallback, etc). */
103	export function emailNote(html: string): string {
104	  return `<p style="margin:16px 0 0;font-family:${FONT};font-size:13px;line-height:1.6;color:${BRAND.muted};">${html}</p>`;
105	}
106	
107	/** Bulletproof CTA button (VML-free but padding-based so it survives Outlook). */
108	export function emailButton(href: string, label: string, accent: Accent = "violet"): string {
109	  const bg = accentColor(accent);
110	  const grad = accent === "violet" ? `background-image:linear-gradient(90deg,${BRAND.violet},${BRAND.violetLight});` : "";
111	  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 6px;"><tr><td align="center" style="border-radius:12px;background-color:${bg};${grad}">
112	    <a href="${href}" style="display:inline-block;padding:14px 34px;font-family:${FONT};font-size:15px;font-weight:600;line-height:1;color:#ffffff;text-decoration:none;border-radius:12px;">${esc(label)}</a>
113	  </td></tr></table>`;
114	}
115	
116	/** Soft rounded panel used to frame a details table / highlighted content. */
117	export function emailPanel(innerHtml: string, accent?: Accent): string {
118	  const border = accent ? accentColor(accent) : BRAND.panelBorder;
119	  const leftRule = accent ? `border-left:4px solid ${accentColor(accent)};` : `border:1px solid ${BRAND.panelBorder};`;
120	  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 18px;background-color:${BRAND.panel};${leftRule}border-radius:12px;">
121	    <tr><td style="padding:18px 20px;">${innerHtml}</td></tr></table>`;
122	}
123	
124	/** Colored status banner (e.g. suspended / payment failed / success). */
125	export function emailBanner(html: string, accent: Accent = "info"): string {
126	  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 18px;background-color:${accentBg(accent)};border-radius:12px;border-left:4px solid ${accentColor(accent)};">
127	    <tr><td style="padding:14px 18px;font-family:${FONT};font-size:14px;line-height:1.55;color:${BRAND.ink};font-weight:600;">${html}</td></tr></table>`;
128	}
129	
130	/** Key/value details table (two columns, hairline rows). Values may hold markup. */
131	export function emailKeyValue(rows: Array<[string, string]>): string {
132	  const body = rows
133	    .map(
134	      ([k, v], i) =>
135	        `<tr>
136	          <td style="padding:11px 0;${i ? `border-top:1px solid ${BRAND.hair};` : ""}font-family:${FONT};font-size:13px;color:${BRAND.muted};vertical-align:top;white-space:nowrap;">${esc(k)}</td>
137	          <td align="right" style="padding:11px 0 11px 16px;${i ? `border-top:1px solid ${BRAND.hair};` : ""}font-family:${FONT};font-size:14px;font-weight:600;color:${BRAND.ink};vertical-align:top;">${v}</td>
138	        </tr>`
139	    )
140	    .join("");
141	  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">${body}</table>`;
142	}
143	
144	/** Monospace code / command block (e.g. an SSH command). */
145	export function emailCode(text: string): string {
146	  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 18px;background-color:#1c1638;border-radius:10px;">
147	    <tr><td style="padding:14px 16px;font-family:'SFMono-Regular',Consolas,'Liberation Mono',Menlo,monospace;font-size:13px;line-height:1.5;color:#d7d2f5;word-break:break-all;">${esc(text)}</td></tr></table>`;
148	}
149	
150	/** Thin divider. */
151	export function emailDivider(): string {
152	  return `<div style="border-top:1px solid ${BRAND.hair};margin:22px 0;line-height:1px;font-size:0;">&nbsp;</div>`;
153	}
154	
155	/**
156	 * The premium email shell. Wraps composed body HTML in the branded, responsive,
157	 * client-safe layout: soft page background → white card with a violet header
158	 * carrying the wordmark → content → footer. `opts.preheader` sets the hidden
159	 * inbox-preview snippet.
160	 */
161	export function wrapEmail(bodyHtml: string, opts: { preheader?: string } = {}): string {
162	  const url = appUrl();
163	  const preheader = opts.preheader
164	    ? `<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:${BRAND.pageBg};opacity:0;">${esc(opts.preheader)}&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;&#8199;</div>`
165	    : "";
166	  return `<!doctype html><html lang="en" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta http-equiv="X-UA-Compatible" content="IE=edge"/><meta name="color-scheme" content="light"/><meta name="supported-color-schemes" content="light"/><title>Nxeon</title></head>
167	<body style="margin:0;padding:0;background-color:${BRAND.pageBg};-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%;">
168	  ${preheader}
169	  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:${BRAND.pageBg};">
170	    <tr><td align="center" style="padding:32px 14px;">
171	      <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;margin:0 auto;">
172	        <tr><td style="border-radius:18px;overflow:hidden;background-color:${BRAND.card};box-shadow:0 8px 30px rgba(40,25,90,0.10);">
173	          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
174	            <!-- Header -->
175	            <tr><td align="center" style="padding:30px 40px 28px;background-color:${BRAND.violet};background-image:linear-gradient(120deg,${BRAND.violetDeep},${BRAND.violetLight});">
176	              <img src="${url}/logo.png" alt="Nxeon" height="30" style="height:30px;width:auto;display:block;border:0;outline:none;text-decoration:none;" />
177	            </td></tr>
178	            <!-- Content -->
179	            <tr><td style="padding:38px 40px 34px;">
180	              ${bodyHtml}
181	            </td></tr>
182	          </table>
183	        </td></tr>
184	        <!-- Footer -->
185	        <tr><td align="center" style="padding:24px 20px 6px;font-family:${FONT};font-size:12px;line-height:1.6;color:${BRAND.muted};">
186	          <a href="${url}/dashboard" style="color:${BRAND.violet};text-decoration:none;margin:0 8px;font-weight:600;">Dashboard</a>
187	          <a href="${url}/help" style="color:${BRAND.violet};text-decoration:none;margin:0 8px;font-weight:600;">Help center</a>
188	          <a href="${url}/dashboard/support" style="color:${BRAND.violet};text-decoration:none;margin:0 8px;font-weight:600;">Support</a>
189	          <div style="margin-top:16px;color:${BRAND.ink};font-weight:700;letter-spacing:.4px;">NXEON CLOUD</div>
190	          <div style="margin-top:4px;color:${BRAND.faint};">High-performance NVMe VPS &middot; game servers &middot; domains</div>
191	          <div style="margin-top:10px;color:${BRAND.faint};">Nxeon Cloud &middot; 128 Cloudfield Way &middot; Wilmington, DE 19801, USA</div>
192	          <div style="margin-top:10px;color:${BRAND.faint};">You're receiving this because you have a Nxeon account.</div>
193	        </td></tr>
194	      </table>
195	    </td></tr>
196	  </table>
197	</body></html>`;
198	}
