200	/** Replace `{{ var }}` placeholders with values from `vars` (missing → empty). */
201	export function substitute(input: string, vars: Record<string, unknown>): string {
202	  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) => {
203	    const v = vars[key];
204	    return v === undefined || v === null ? "" : String(v);
205	  });
206	}
207	
208	/**
209	 * Minimal built-in defaults used when a template row is missing or disabled.
210	 * These are intentionally plain — the real, branded copy lives in the DB (see
211	 * `prisma/seed-email-templates.ts`).
212	 */
213	const DEFAULTS: Record<string, { subject: string; body: string }> = {
214	  welcome: {
215	    subject: "Welcome to Nxeon",
216	    body: `${emailHeading("Welcome, {{name}}!")}${emailParagraph("Your Nxeon account is ready. Deploy your first NVMe VPS in minutes.")}`,
217	  },
218	  password_reset: {
219	    subject: "Reset your Nxeon password",
220	    body: `${emailHeading("Reset your password")}${emailParagraph("Use the button below to set a new password. It expires in 1 hour.")}${emailButton("{{resetUrl}}", "Reset password")}`,
221	  },
222	};
223	
224	const GENERIC_FALLBACK = (key: string) => ({
225	  subject: "A message from Nxeon",
226	  body: `${emailHeading("Nxeon")}${emailParagraph(`This notification (<code>${esc(key)}</code>) has no configured template.`)}`,
227	});
228	
229	export type RenderedEmail = { subject: string; html: string; template: string };
230	
231	/**
232	 * Render a stored (or default) template for `key`, substituting `vars`,
233	 * returning the final subject and full wrapped HTML ready to send/preview.
234	 */
235	export async function renderTemplate(key: string, vars: Record<string, unknown> = {}): Promise<RenderedEmail> {
236	  let subject: string;
237	  let body: string;
238	
239	  let row: { subject: string; html: string; enabled: boolean } | null = null;
240	  try {
241	    row = await (await prisma()).emailTemplate.findUnique({
242	      where: { key },
243	      select: { subject: true, html: true, enabled: true },
244	    });
245	  } catch {
246	    row = null;
247	  }
248	
249	  if (row && row.enabled) {
250	    subject = row.subject;
251	    body = row.html;
252	  } else {
253	    const d = DEFAULTS[key] ?? GENERIC_FALLBACK(key);
254	    subject = d.subject;
255	    body = d.body;
256	  }
257	
258	  const preheader = typeof vars.preheader === "string" ? (vars.preheader as string) : undefined;
259	  return {
260	    template: key,
261	    subject: substitute(subject, vars),
262	    html: wrapEmail(substitute(body, vars), { preheader }),
263	  };
264	}
265	
266	/**
267	 * Render a *draft* (unsaved) subject/body with sample vars — used by the admin
268	 * editor's live preview and by the seed preview. Same wrapping as a real send.
269	 */
270	export function renderDraft(subject: string, body: string, vars: Record<string, unknown> = {}): RenderedEmail {
271	  const preheader = typeof vars.preheader === "string" ? (vars.preheader as string) : undefined;
272	  return {
273	    template: "draft",
274	    subject: substitute(subject, vars),
275	    html: wrapEmail(substitute(body, vars), { preheader }),
276	  };
277	}
