66	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
67	  if (!c.host) {
68	    // Local MTA fallback (Postfix/sendmail on the host)
69	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
70	  }
71	  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
72	  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
73	  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
74	  // on while telling TLS the name to validate against (and sets SNI accordingly).
75	  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
76	  return nodemailer.createTransport({
77	    host: c.host,
78	    port: c.port,
79	    secure: c.secure,
80	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
81	    ...(servername ? { tls: { servername } } : {}),
82	  });
83	}
