1	/**
2	 * Marketing Agent Phase 1 — DISCOVERY SWEEP (worker task).
3	 *
4	 * Runs on the worker loop (hourly). For each ACTIVE MarketingSource it:
5	 *   1. Reads the public feed (Reddit public JSON / HN Algolia / RSS) — read-only.
6	 *   2. Dedupes by (sourceId, externalId) and stores NEW matches as MarketingSignal.
7	 *   3. For high-score NEW signals, generates a DISCLOSED draft reply via Claude
8	 *      and stores it as MarketingDraft (signal -> DRAFTED). If no Anthropic key
9	 *      is configured, it skips drafting gracefully and leaves the signal NEW with
10	 *      a note.
11	 *
12	 * CRITICAL: this sweep NEVER posts to any external platform. It only reads public
13	 * data and writes to our own DB. Every "post" in this system is a human action
14	 * recorded as a bookkeeping flag. See lib/marketing/discovery.ts + draft-gen.ts.
15	 */
16	
17	import { db } from "../lib/db";
18	import { getSettingBool, getSettingInt } from "../lib/settings";
19	import { discoverForSource } from "../lib/marketing/discovery";
20	import { generateDraft } from "../lib/marketing/draft-gen";
21	import { platformKeyConfigured } from "../lib/anthropic";
22	
23	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
24	
25	/** Max signals we auto-draft per sweep (bounds Anthropic spend + latency). */
26	const DRAFT_BUDGET_PER_SWEEP = 8;
27	
28	export async function marketingDiscoverySweep(): Promise<void> {
29	  // Operator kill-switch. Defaults ON, but a single Setting flip pauses discovery
30	  // without a deploy (matches the platform's other toggles).
31	  if (!(await getSettingBool("marketing_monitor_enabled", true))) return;
32	
33	  // Only draft for signals at/above this score — keeps the reviewer's queue high
34	  // signal and Anthropic usage low. Tunable from Settings.
35	  const draftThreshold = await getSettingInt("marketing_draft_threshold", 55);
36	
37	  let sources: { id: string; type: string; target: string; keywords: string[] }[] = [];
38	  try {
39	    sources = await db.marketingSource.findMany({ where: { active: true } });
40	  } catch {
41	    // Table not migrated yet (e.g. prod before `prisma db push`). No-op.
42	    return;
43	  }
44	  if (sources.length === 0) return;
45	
46	  let stored = 0;
47	  for (const source of sources) {
48	    let candidates;
49	    try {
50	      candidates = await discoverForSource(source);
51	    } catch (e) {
52	      console.error(`[marketing] discover error (${source.type}:${source.target})`, e);
53	      continue;
54	    }
55	    for (const c of candidates) {
56	      try {
57	        // Dedupe on the unique (sourceId, externalId): create only if new.
58	        const existing = await db.marketingSignal.findUnique({
59	          where: { sourceId_externalId: { sourceId: source.id, externalId: c.externalId } },
60	          select: { id: true },
61	        });
62	        if (existing) continue;
63	        await db.marketingSignal.create({
64	          data: {
65	            sourceId: source.id,
66	            externalId: c.externalId,
67	            url: c.url,
68	            title: c.title.slice(0, 300),
69	            excerpt: c.excerpt.slice(0, 1000),
70	            author: c.author.slice(0, 120),
71	            matchedKeywords: c.matchedKeywords,
72	            score: c.score,
73	            status: "NEW",
74	          },
75	        });
76	        stored++;
77	      } catch (e) {
78	        console.error("[marketing] signal store error", e);
79	      }
80	    }
81	    await sleep(1500); // pace between sources — polite, rate-limit friendly
82	  }
83	  if (stored > 0) console.log(`[marketing] stored ${stored} new signal(s)`);
84	
85	  await draftNewSignals(draftThreshold);
86	}
