88	/**
89	 * Draft disclosed replies for the top NEW signals. If no Anthropic key is set,
90	 * mark the signals with a note and leave them NEW (a human can draft manually).
91	 */
92	async function draftNewSignals(threshold: number): Promise<void> {
93	  let newSignals;
94	  try {
95	    newSignals = await db.marketingSignal.findMany({
96	      where: { status: "NEW", score: { gte: threshold } },
97	      orderBy: [{ score: "desc" }, { detectedAt: "desc" }],
98	      take: DRAFT_BUDGET_PER_SWEEP,
99	    });
100	  } catch {
101	    return;
102	  }
103	  if (newSignals.length === 0) return;
104	
105	  if (!platformKeyConfigured()) {
106	    // Skip gracefully — record why, once, so the UI can explain the queue is idle.
107	    for (const s of newSignals) {
108	      try {
109	        await db.marketingSignal.update({
110	          where: { id: s.id },
111	          data: { note: "No Anthropic key configured — draft manually or set ANTHROPIC_API_KEY." },
112	        });
113	      } catch {
114	        /* ignore */
115	      }
116	    }
117	    return;
118	  }
119	
120	  for (const s of newSignals) {
121	    try {
122	      const body = await generateDraft({
123	        title: s.title,
124	        excerpt: s.excerpt,
125	        url: s.url,
126	        matchedKeywords: s.matchedKeywords,
127	      });
128	      if (!body) {
129	        await db.marketingSignal.update({
130	          where: { id: s.id },
131	          data: { note: "Draft generation returned nothing (API error) — retry or draft manually." },
132	        });
133	        continue;
134	      }
135	      // Channel mirrors the source type where possible.
136	      const src = await db.marketingSource.findUnique({ where: { id: s.sourceId }, select: { type: true } });
137	      await db.marketingDraft.create({
138	        data: { signalId: s.id, body, channel: src?.type ?? "reddit", status: "DRAFT" },
139	      });
140	      await db.marketingSignal.update({
141	        where: { id: s.id },
142	        data: { status: "DRAFTED", note: "" },
143	      });
144	    } catch (e) {
145	      console.error("[marketing] draft error", e);
146	    }
147	  }
148	}
