1	// Cold Email Engine — send-queue processor (Phase 2).
2	//
3	// Registered on the worker loop (worker/index.ts) and gated HARD behind the
4	// `cold_email_sending_enabled` master kill-switch: while that Setting is false
5	// this sweep returns immediately and NOTHING is scheduled, rendered, or sent.
6	//
7	// For each SENDING campaign it:
8	//   1. Re-checks brand send-eligibility (compliance + reputation isolation +
9	//      circuit-breaker pause). A blocked brand is skipped, never sent.
10	//   2. Expands the list → contacts → schedules a ColdSend per SequenceStep,
11	//      honouring delayDays (idempotent via the unique (campaign, contact, step)).
12	//   3. Sends due rows, enforcing at SEND TIME: suppression re-check, per-inbox
13	//      daily cap with the warmup ramp, and the send window — writing ColdSend
14	//      status (SENT/FAILED/SUPPRESSED) + an EmailEvent, throttled with jitter.
15	//
16	// Every count comes from the DB; the only external call is the SMTP send itself,
17	// which is unreachable in tests because the kill-switch keeps this inert.
18	
19	import { db } from "../lib/db";
20	import { getSetting, getSettingBool } from "../lib/settings";
21	import {
22	  isSuppressed,
23	  evaluateSendEligibility,
24	  protectedDomainSet,
25	  effectiveDailyCap,
26	  openTrackingToken,
27	  type SuppressionLike,
28	} from "../lib/coldemail/compliance";
29	import { buildMessage, getTransport, type SendIdentity, type MailTransport } from "../lib/coldemail/sender";
30	import { inboxAllowedVolume } from "../lib/coldemail/warmup";
31	import { selectNextInbox, type RotationInbox } from "../lib/coldemail/rotation";
32	import { isMailableStatus } from "../lib/coldemail/leaddb";
33	import { logEvent } from "../lib/log";
34	
35	/**
36	 * A brand's rotation pool for this sweep: the ACTIVE inboxes on its authenticated
37	 * domains, each with the send identity + today's warmup-clamped allowance and the
38	 * live rotation candidate the selector mutates as sends go out.
39	 */
40	type PoolInbox = {
41	  candidate: RotationInbox;
42	  identity: SendIdentity;
43	  sendingDomainId: string;
44	};
45	
46	/**
47	 * Load a brand's rotation pool. Returns [] when the brand has no inboxes — the
48	 * worker then falls back to the Phase 2 brand-level cap path unchanged. Only
49	 * inboxes on a domain with SPF+DKIM+DMARC all verified are authenticated (authGreen).
50	 */
51	async function loadBrandRotationPool(brandId: string, brand: SendIdentity, now: Date): Promise<PoolInbox[]> {
52	  let inboxes;
53	  try {
54	    inboxes = await db.inbox.findMany({
55	      // Only ACTIVE inboxes on a domain that is not paused/burned. A domain-level
56	      // auto-pause therefore takes every one of its inboxes out of rotation.
57	      where: { status: "ACTIVE", sendingDomain: { brandId, status: { notIn: ["PAUSED", "BURNED"] } } },
58	      include: { sendingDomain: true },
59	    });
60	  } catch {
61	    return []; // tables not migrated on this env — behave like Phase 2
62	  }
63	  if (inboxes.length === 0) return [];
64	
65	  const dayStart = startOfUtcDay(now);
66	  const pool: PoolInbox[] = [];
67	  for (const ib of inboxes) {
68	    const d = ib.sendingDomain;
69	    const authGreen = !!(d?.spfVerified && d?.dkimVerified && d?.dmarcVerified);
70	    const allowedToday = inboxAllowedVolume({
71	      warmupStartedAt: ib.warmupStartedAt,
72	      plan: { startCap: ib.startCap, targetCap: ib.targetCap, rampDays: ib.rampDays },
73	      dailyCap: ib.dailyCap,
74	      healthScore: ib.healthScore,
75	      adaptive: ib.strategy === "ADAPTIVE",
76	      now,
77	    });
78	    const sentToday = await db.coldSend.count({ where: { inboxId: ib.id, sentAt: { gte: dayStart } } });
79	    pool.push({
80	      sendingDomainId: ib.sendingDomainId,
81	      candidate: {
82	        id: ib.id,
83	        status: ib.status as RotationInbox["status"],
84	        allowedToday,
85	        sentToday,
86	        authGreen,
87	        lastSendAt: ib.lastSendAt,
88	        minGapSeconds: ib.minGapSeconds,
89	      },
90	      // Send AS the inbox address, keeping the brand's name/postal/reply-to. This is
91	      // what makes rotation real — each message goes out from a different mailbox.
92	      identity: {
93	        ...brand,
94	        fromEmail: ib.email,
95	        sendingDomain: d ? `${d.subdomain ? d.subdomain + "." : ""}${d.domain}` : brand.sendingDomain,
96	      },
97	    });
98	  }
99	  return pool;
100	}
