392	/** Mark a campaign DONE once nothing is left QUEUED (all sends terminal). */
393	async function maybeCompleteCampaign(campaignId: string): Promise<void> {
394	  const remaining = await db.coldSend.count({ where: { campaignId, status: "QUEUED" } });
395	  if (remaining > 0) return;
