252	/**
253	 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
254	 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
255	 *
256	 * If the archive listing cannot be read we do NOT silently fall back to the raw
257	 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
258	 * and a provision that fails is recoverable while a cross-tenant disclosure is
259	 * not. The job retries; an operator sees why.
260	 */
261	async function allocateFreshVmid(conn: any): Promise<number> {
262	  const candidate = await conn.nextVmid();
263	  const archived = await archivedVmids(conn);
264	
265	  // Ids already in use, so skipping forward cannot land on a live VM. Read
266	  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
267	  let taken = new Set<number>();
268	  try {
269	    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
270	    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
271	  } catch {
272	    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
273	    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
274	  }
275	
276	  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
277	  if (skipped.length > 0) {
278	    console.warn(
279	      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
280	        `from a previous server; allocated ${vmid} instead`
281	    );
282	  }
283	  return vmid;
284	}
