286	async function provision(job: Job) {
287	  const server = await loadServer(job);
288	  // Clear any stale failure reason from a previous attempt as this run starts, so
289	  // a successful retry doesn't leave the last error hanging around on the row.
290	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null } });
291	
292	  if (SANDBOX) {
293	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
294	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
295	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
296	    const password = generatePassword();
297	    const ip = sandboxIp(vmid);
298	    await db.server.update({
299	      where: { id: server.id },
300	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
301	    });
302	    await notify(
303	      server.userId,
304	      `Server ${server.hostname} is ready`,
305	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
306	      `/dashboard/servers/${server.id}`
307	    );
308	    // Post-purchase review request (once per server, skipped if no profiles set).
309	    await sendReviewRequestForServer(server.id);
310	    return;
311	  }
312	
313	  const { conn, row: nodeRow } = await nodeFor(server);
314	  const storage = server.plan.storageTier === "hdd"
315	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
316	    : nodeRow?.storageNvme ?? "vmdata";
317	
318	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
319	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
320	  // server's vzdump archives, so the id freed by a deletion comes back carrying
321	  // the old owner's backups — which every backup surface then attributes to the
322	  // new customer (listBackups/requestRestore key on vmid alone). See
323	  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
324	  // keeps the vmid already persisted on the row.
325	  const vmid = server.vmid ?? (await allocateFreshVmid(conn));
326	  const password = generatePassword();
327	
328	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
329	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
330	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
331	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
332	  const { getSettingBool: _settingBool } = await import("../lib/settings");
333	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
334	  if (wantDedicated && ovhConfigured()) {
335	    try {
336	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
337	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
338	      dedicated = await allocateDedicatedIp(server.id, vmid);
339	    } catch (e) {
340	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
341	    }
342	  }
343	  // Node-aware + transactionally-claimed allocation (passing the server id enables
344	  // the claim path, so two concurrent provisions can't pick the same IP/port).
345	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
346	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
347	
348	  await db.server.update({
349	    where: { id: server.id },
350	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
351	  });
352	
353	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
354	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
355	  // (worker restart mid-clone, or any transient failure in the steps below) would
356	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
357	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
358	  // the clone is idempotent, so skip it when the VM is already present.
359	  let vmAlreadyExists = false;
360	  try {
361	    await conn.vmStatus(vmid);
362	    vmAlreadyExists = true;
363	  } catch {
364	    vmAlreadyExists = false;
365	  }
366	  if (vmAlreadyExists) {
367	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
368	  } else {
