408	    cores: server.plan.cpuCores,
409	    memory: server.plan.ramMB,
410	    ciuser: "root",
411	    cipassword: password,
412	    sshkeys,
413	    nameserver: "1.1.1.1 8.8.8.8",
414	    onboot: 1,
415	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
416	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
417	  };
418	  if (dedicated) {
419	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
420	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
