504	/**
505	 * Tear down a VM. Idempotent and verified — see `destroyVmIdempotent` in
506	 * lib/proxmox.ts for the incident and the ladder. The bare version of this
507	 * function threw on an already-absent VM, which is what made a retried REINSTALL
508	 * destroy a customer's server permanently.
509	 */
510	async function destroyVm(conn: any, vmid: number): Promise<DestroyOutcome> {
511	  const host: VmDestroyHost = {
512	    probe: async (id) => {
513	      try {
514	        await conn.vmStatus(id);
515	        return "present";
516	      } catch (e) {
517	        // Only a vmid-anchored "config does not exist" proves absence. Anything
518	        // else (auth, network, a locked node) is genuinely unknown and must not
519	        // be read as "already gone".
520	        return isVmAbsentError(e, id) ? "absent" : "unknown";
521	      }
522	    },
523	    stop: async (id) => {
524	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
525	      await conn.waitForTask(stopUpid);
526	    },
527	    destroy: async (id) => {
528	      const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, {
529	        "destroy-unreferenced-disks": 1,
530	        purge: 1,
531	      });
532	      await conn.waitForTask(delUpid, 600_000);
533	    },
534	  };
535	  return destroyVmIdempotent(host, vmid);
536	}
