538	async function remove(job: Job) {
539	  const server = await loadServer(job);
540	  const { conn } = await nodeFor(server);
541	  if (!SANDBOX && server.vmid) {
542	    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
543	    // so the absent case no longer needs to be caught here at all. The catch that
544	    // remains is narrowed to this vmid: it used to swallow any error containing
545	    // "does not exist", which also matches `storage 'vmdata' does not exist` and
546	    // `volume ... does not exist` — errors that mean the VM is very much still
547	    // running. On one of those the handler proceeded to delete the Server row and
548	    // every Volume row pinned to it, leaving a live VM with no database record:
549	    // invisible to billing, invisible to the panel, still holding the customer's
550	    // data and impossible to reach through any surface we own.
551	    try {
552	      await destroyVm(conn, server.vmid);
553	    } catch (e: any) {
554	      if (!isVmAbsentError(e, server.vmid)) throw e;
555	    }
556	    // Best-effort: remove the per-server cloud-init snippet
557	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
558	  }
559	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
560	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
561	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
562	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
563	  // diskName and keep billing forever. Remove them and notify the owner. (The
564	  // reinstall guard already blocks the accidental case; a full server delete is an
565	  // intentional teardown, so we drop the volumes with it.)
566	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
567	  if (orphanVolumes.length > 0) {
568	    await db.volume.deleteMany({ where: { serverId: server.id } });
569	    for (const v of orphanVolumes) {
570	      await notify(
571	        v.userId,
572	        `Volume "${v.name}" was removed`,
573	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
574	        "/dashboard/volumes",
575	      ).catch(() => {});
576	    }
577	  }
578	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
579	  // server.delete cascade removes THIS running Job row — the success-path
580	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
581	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
582	  await db.server.delete({ where: { id: server.id } });
583	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
584	  // DELETE, which then dies on "Server not found" and the sync is never retried
585	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
586	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
587	}
