589	async function reinstall(job: Job) {
590	  const server = await loadServer(job);
591	  if (SANDBOX) {
592	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
593	    await notify(
594	      server.userId,
595	      `Server ${server.hostname} reinstalled (sandbox)`,
596	      "The sandbox server was reinstalled (no real VM was touched).",
597	      `/dashboard/servers/${server.id}`
598	    );
599	    return;
600	  }
601	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
602	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
603	  // EVERY disk the vmid owns, including attached block-storage Volume disks
604	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
605	  // by that vmid, and both purge and the default destroy (which removes disks
606	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
607	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
608	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
609	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
610	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
611	  // can be re-attached after the reinstall. This runs BEFORE any status change or
612	  // destructive call, so a blocked reinstall touches nothing.
613	  //
614	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
615	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
616	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
617	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
618	  // let the worst path through: fill a volume, Detach (the UI says "Data is
619	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
620	  // Detaching is therefore NOT sufficient protection, and telling the customer to
621	  // detach was wrong advice; they must delete the volume (which destroys just
622	  // that disk, deliberately) or move it to another server first.
623	  const pinnedVolumes = await db.volume.findMany({
624	    where: { serverId: server.id },
625	  });
626	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
627	  const realPinned = pinnedVolumes.filter(
628	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
629	  );
630	  if (realPinned.length > 0) {
631	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
632	    throw new Error(
633	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
634	        `Reinstalling purges every disk this server owns — including detached volumes ` +
635	        `that are still assigned to it — and that cannot be undone.`
636	    );
637	  }
638	
639	  const { conn } = await nodeFor(server);
640	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
641	  if (server.vmid) await destroyVm(conn, server.vmid);
642	  await provision(job);
643	}
