645	async function suspend(job: Job, unsuspend: boolean) {
646	  const server = await loadServer(job);
647	  if (SANDBOX) {
648	    if (unsuspend) {
649	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null, suspendReason: null } });
650	    } else {
651	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
652	    }
653	    return;
654	  }
655	  const { conn, row: nodeRow } = await nodeFor(server);
656	  if (unsuspend) {
657	    // The dedicated IP was returned to the pool while suspended — re-allocate one
658	    // and reconfigure the public network before starting the VM back up.
659	    if (server.vmid) {
660	      const { getSettingBool: _sb } = await import("../lib/settings");
661	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
662	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
663	      let reconfigured = alreadyHas ? true : false;
664	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
665	        try {
666	          const d = await allocateDedicatedIp(server.id, server.vmid);
667	          if (d) {
668	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
669	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
670	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
671	            });
672	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
673	            reconfigured = true;
674	          }
675	        } catch (e) {
676	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
677	        }
678	      }
679	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
680	      // the Virtual MAC + failover IP that suspend released back to the pool — that
681	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
682	      // with a valid, non-conflicting network instead of a dead public config.
683	      if (!reconfigured) {
684	        try {
685	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
686	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
687	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
688	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
689	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
690	          });
691	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
692	        } catch (e) {
693	          console.error("[worker] NAT fallback on unsuspend failed", e);
694	        }
695	      }
696	    }
697	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null, suspendReason: null } });
698	    // Not fatal to the unsuspend itself (the customer is paid up and the VM must
699	    // come back), but never silent: an unproved sync is logged with its reason.
700	    if (!SANDBOX) await syncPortForwardsBestEffort(`unsuspend ${server.hostname}`);
701	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
702	    await conn.waitForTask(upid);
703	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
704	  } else {
705	    try {
706	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
707	      await conn.waitForTask(upid);
708	    } catch { /* may already be stopped */ }
709	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
710	    if (!SANDBOX) await syncPortForwardsBestEffort(`suspend ${server.hostname}`);
711	    // Return the dedicated IP to the pool while the server is suspended, so it
712	    // can be handed to a paying server. Re-allocated on unsuspend.
713	    if (ovhConfigured()) {
714	      try {
715	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
716	        if (had) {
717	          await releaseDedicatedIp(server.id);
718	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
719	          // so leaving the released IP here makes the next server that claims it fail
720	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
