722	          await db.server.update({
723	            where: { id: server.id },
724	            data: { ipAddress: null, ipv6: null },
725	          });
726	        }
727	      } catch (e) {
728	        console.error("[worker] release dedicated IP on suspend failed", e);
729	      }
730	    }
731	  }
732	}
