742	/**
743	 * Tell the customer their server failed to provision. Before this, a terminal
744	 * PROVISION failure flipped the server to ERROR and sent NOTHING — the customer
745	 * paid, then sat on a dead screen with a red dot and no explanation. Persists a
746	 * short human reason on `Server.provisionError` (surfaced in the ERROR banner on
747	 * the detail page), drops an in-app notification, and emails them. Best-effort on
748	 * every leg — a failed notification must never mask the underlying job failure.
749	 *
750	 * `error` is the redacted Job.error; we keep a trimmed copy for the customer.
751	 */
752	async function notifyProvisionFailed(
753	  server: { id: string; userId: string; hostname: string },
754	  error: string,
755	): Promise<void> {
756	  // A concise, customer-facing reason. The raw Job.error can be a 2000-char stack;
757	  // the first line is almost always the meaningful message.
758	  const reason = (error.split("\n")[0] || error).trim().slice(0, 300);
759	  try {
760	    await db.server.update({ where: { id: server.id }, data: { provisionError: reason } });
761	  } catch (e) {
762	    console.error("[worker] persist provisionError failed", e);
763	  }
764	  // If this VM backs a managed NxCloud, mark the wrapper FAILED too — otherwise a
765	  // failed nxcloud provision leaves the instance stuck on "setting up" forever
766	  // while the backing Server sits in ERROR. Its dashboard card reads this to show
767	  // the failed/retry state (components/customer/NxcloudClient.tsx).
768	  try {
769	    await db.nxCloudInstance.updateMany({
770	      where: { serverId: server.id, status: { notIn: ["DELETING", "ACTIVE"] } },
771	      data: { status: "FAILED", error: reason },
772	    });
773	  } catch (e) {
774	    console.error("[worker] mark nxcloud instance failed", e);
775	  }
776	  await notify(
777	    server.userId,
778	    `We couldn't set up ${server.hostname}`,
779	    `Provisioning failed and our team has been notified. You can retry it or contact support from the server page.`,
780	    `/dashboard/servers/${server.id}`,
781	  );
782	  try {
783	    const { sendMail, emails } = await import("../lib/mailer");
784	    const user = await db.user.findUnique({ where: { id: server.userId }, select: { email: true } });
785	    if (user?.email) {
786	      const tpl = emails.provisionFailed({ hostname: server.hostname, reason });
787	      await sendMail({
788	        to: user.email,
789	        subject: tpl.subject,
790	        html: tpl.html,
791	        template: tpl.template,
792	        userId: server.userId,
793	        // No `kind` → always send. A paid-for server that failed to build is a
794	        // service-delivery failure the customer must hear about.
795	      });
796	    }
797	  } catch (e) {
798	    console.error("[worker] provision-failure email failed", e);
799	  }
800	}
