802	async function resize(job: Job) {
803	  const server = await loadServer(job);
804	  const payload = (job.payload ?? {}) as { planId?: string };
805	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
806	  if (!newPlan) throw new Error("resize: target plan not found");
807	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
808	
809	  // Any separately-purchased extra disk is ADDITIVE to whichever plan the server
810	  // sits on, so it survives the plan change untouched — `Server.extraDiskGB` is
811	  // never written here. Sizes below are therefore always the EFFECTIVE size
812	  // (new plan + extra); using the bare plan size would ask Proxmox to SHRINK the
813	  // disk of any server carrying extra storage, and the resize would hard-fail.
814	  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, server.extraDiskGB);
815	  const currentTotalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
816	  const diskLine =
817	    server.extraDiskGB > 0
818	      ? `${newTotalDiskGB} GB disk (${newPlan.diskGB} GB plan + ${server.extraDiskGB} GB added storage)`
819	      : `${newPlan.diskGB} GB disk`;
820	
821	  if (SANDBOX) {
