870	    );
871	    return;
872	  }
873	  const { conn } = await nodeFor(server);
874	  let upid: string;
875	  if (op === "create") {
876	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
877	  } else if (op === "delete") {
878	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
879	  } else {
880	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
881	  }
882	  await conn.waitForTask(upid, 600_000);
883	  if (op === "rollback") {
884	    // rollback leaves the VM stopped; bring it back if the server should be running
885	    const current = await db.server.findUnique({ where: { id: server.id } });
886	    if (current?.status === "RUNNING") {
