1017	    // off the hypervisor and our window would come off the worker's clock.
1018	    const before = await listBackupsOn(conn, vmid);
1019	
1020	    const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
1021	      vmid,
1022	      storage: "backup",
1023	      mode: "snapshot",
1024	      compress: "zstd",
1025	    });
