input.content:
// Deploy WIN-BACK — re-engagement sweep (worker task).
//
// Registered on the worker loop (worker/index.ts) and gated HARD behind the
// `deploy_winback_enabled` master kill-switch (env `DEPLOY_WINBACK_ENABLED` also
// enables it). While that flag is false this sweep returns immediately and
// NOTHING is queried, rendered, or sent — so shipping the code mails no one until
// a human turns it on.
//
// What it does when enabled: finds signed-in users who STARTED the deploy wizard
// (DeployFunnelEvent type='step') and abandoned it — their most recent step is
// older than a short cooldown (don't email mid-session) but newer than a max age
// (stay timely) — excludes anyone who finished, already owns a server, is
// unverified/opted-out, or has already had this email, then sends each a branded
// win-back offering a first-month discount coupon. Modeled on worker/marketing.ts
// (marketingDiscoverySweep) and worker/coldemail.ts (coldEmailSendSweep): same
// flag gate, per-item try/catch, send cap, and count logging.
//
// COMPLIANCE: the send uses the PRODUCT/marketing NotifyKind (`product_news`), so
// `sendMail` → `mayDeliverTo` enforces the customer's marketing opt-out, and the
// shared email shell carries the unsubscribe footer. Suppression is enforced the
// same central way every other send is.

import { db } from "../lib/db";
import { getSettingBool } from "../lib/settings";
import { sendMail, emails } from "../lib/mailer";
import { mayDeliverTo } from "../lib/prefs";
import { appUrl } from "../lib/email-render";

/**
 * The campaign coupon code — ONE constant. The owner creates a matching coupon in
 * the Coupons engine (any-plan, first-month, this percent). Nothing here mints it;
 * the email just presents the code.
 */
export const WINBACK_COUPON_CODE = "COMEBACK50";
/** Percent off the first month the campaign advertises (must match the coupon). */
export const WINBACK_PERCENT_OFF = 50;

/** EmailLog.template tag used both to WRITE the send and to DEDUPE against it. */
const WINBACK_TEMPLATE_TAG = "deploy_winback";

/**
 * COOLDOWN — a user whose latest wizard step is more recent than this is treated
 * as still mid-session and is NOT emailed (avoids interrupting an active setup).
 */
const COOLDOWN_MS = 2 * 60 * 60 * 1000; // 2 hours
/**
 * MAX_AGE — a user whose latest wizard step is older than this is too cold to be
 * timely and is skipped (the offer should feel like a same-week nudge).
 */
const MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000; // 7 days

/** Hard cap on sends per sweep run — bounds a burst if a backlog builds up. */
const MAX_SENDS_PER_SWEEP = 25;

/** Gentle pacing between sends so a run never blasts the SMTP relay. */
const SEND_GAP_MS = 1200;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/**
 * A friendly, non-stale expiry label ("Sep 30"): the last day of NEXT month. The
 * owner sets the real coupon expiry ~here; the copy stays accurate week to week
 * rather than hardcoding a date that goes stale.
 */
function winbackExpiresLabel(now = new Date()): string {
  // Day 0 of month+2 == last day of month+1.
  const lastDayNextMonth = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 2, 0));
  return lastDayNextMonth.toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
}

/**
 * The win-back sweep. GATED by `deploy_winback_enabled` (or env
 * `DEPLOY_WINBACK_ENABLED`) — the single line that keeps everything below inert
 * until a human enables it on prod.
 */
export async function deployWinbackSweep(): Promise<void> {
  // ===== MASTER KILL-SWITCH (first line) =====
  const envOn = process.env.DEPLOY_WINBACK_ENABLED === "true";
  if (!envOn && !(await getSettingBool("deploy_winback_enabled", false))) return;

  const now = Date.now();
  const cooldownCutoff = new Date(now - COOLDOWN_MS); // latest step must be BEFORE this
  const maxAgeCutoff = new Date(now - MAX_AGE_MS); // latest step must be AFTER this

  // CANDIDATES: for each user who has any wizard STEP event, the timestamp of
  // their most recent step. Grouping (not a raw findMany) is what lets us test the
  // LATEST step against the window — so a user still clicking through the wizard
  // right now (a recent step) is never selected even if they also have an older one.
  let grouped: { userId: string | null; _max: { createdAt: Date | null } }[];
  try {
    grouped = await db.deployFunnelEvent.groupBy({
      by: ["userId"],
      where: { type: "step", userId: { not: null } },
      _max: { createdAt: true },
    });
  } catch {
    // Table not present on this environment yet — no-op (mirrors the other sweeps).
    return;
  }

  const candidateIds = grouped
    .filter((g): g is { userId: string; _max: { createdAt: Date } } => {
      const last = g._max.createdAt;
      return !!g.userId && !!last && last < cooldownCutoff && last > maxAgeCutoff;
    })
    .map((g) => g.userId);
  if (candidateIds.length === 0) return;

  // ---- Batched exclusions (cheap set lookups, no N+1) ----------------------
  // Finished the wizard at least once → converted intent, never win-back.
  const completed = await db.deployFunnelEvent.findMany({
    where: { userId: { in: candidateIds }, type: "complete" },
    distinct: ["userId"],
    select: { userId: true },
  });
  const completedIds = new Set(completed.map((c) => c.userId));

  // Already sent this win-back → dedupe. Matches EmailLog rows tagged with our
  // template. NOTE: EmailLog is retained ~90 days (lib/email-render
  // emailLogRetentionDays), so this is "once per user" in practice bounded to at
  // most once per retention window — a user who abandoned again 90+ days later
  // (and still hasn't converted) may be re-engaged once more, which is intended.
  const alreadySent = await db.emailLog.findMany({
    where: { userId: { in: candidateIds }, template: WINBACK_TEMPLATE_TAG, status: "SENT" },
    distinct: ["userId"],
    select: { userId: true },
  });
  const alreadySentIds = new Set(alreadySent.map((e) => e.userId).filter((x): x is string => !!x));

  // User rows: email + verification + whether they own any server (existing/
  // converting customer). _count.servers > 0 excludes them.
  const users = await db.user.findMany({
    where: { id: { in: candidateIds } },
    select: {
      id: true,
      name: true,
      email: true,
      emailVerifiedAt: true,
      _count: { select: { servers: true } },
    },
  });
  const userById = new Map(users.map((u) => [u.id, u]));

  const expiresLabel = winbackExpiresLabel(new Date(now));
  const deployUrl = `${appUrl()}/dashboard/deploy`;

  let considered = 0;
  let sent = 0;
  let skipped = 0;
  let failed = 0;

  for (const userId of candidateIds) {
    if (sent >= MAX_SENDS_PER_SWEEP) break;
    considered++;

    const u = userById.get(userId);
    // Exclusions: finished the wizard; owns a server; already emailed; no email;
    // email not verified.
    if (!u) { skipped++; continue; }
    if (completedIds.has(userId)) { skipped++; continue; }
    if (u._count.servers > 0) { skipped++; continue; }
    if (alreadySentIds.has(userId)) { skipped++; continue; }
    if (!u.email) { skipped++; continue; }
    if (!u.emailVerifiedAt) { skipped++; continue; }

    // Marketing opt-out / suppression. `sendMail` enforces this centrally too, but
    // pre-checking lets us skip cleanly (and not attempt a send we'd suppress).
    let deliverable = true;
    try {
      deliverable = await mayDeliverTo(userId, "product_news", "email");
    } catch {
      deliverable = true; // fail open — mirrors mayDeliverTo's own contract
    }
    if (!deliverable) { skipped++; continue; }

    try {
      const built = emails.deployWinback({
        name: u.name,
        couponCode: WINBACK_COUPON_CODE,
        percentOff: WINBACK_PERCENT_OFF,
        expiresLabel,
        deployUrl,
      });
      // Marketing kind → opt-outs honoured; template tag → EmailLog dedupe row.
      const ok = await sendMail({
        to: u.email,
        subject: built.subject,
        html: built.html,
        template: built.template, // "deploy_winback" — the dedupe tag
        userId,
        kind: "product_news",
      });
      if (ok) sent++;
      else failed++;
    } catch (e) {
      failed++;
      console.error(`[winback] send failed for user ${userId}`, e);
    }

    await sleep(SEND_GAP_MS);
  }

  if (sent > 0 || failed > 0) {
    console.log(
      `[winback] sweep complete — considered ${considered}/${candidateIds.length}, sent ${sent}, skipped ${skipped}, failed ${failed}`,
    );
  }
}

