/**
 * Preview the deploy WIN-BACK email — renders `emails.deployWinback(...)` with
 * sample data and writes the full HTML to disk so the owner can open it.
 *
 * Run:  npx tsx scripts/preview-deploy-winback.ts
 * Out:  /opt/nxeon-wt-winback/winback-preview.html
 *
 * Imports ONLY the pure template builder (lib/email-templates) — `deployWinback`
 * is string composition with no DB access, so this touches no database and sends
 * no email. `@/` path alias resolves under tsx (same as the other repo scripts).
 */
import { writeFile } from "node:fs/promises";
import { emails } from "../lib/email-templates";
import { appUrl } from "../lib/email-render";

const OUT = "/opt/nxeon-wt-winback/winback-preview.html";

async function main() {
  const built = emails.deployWinback({
    name: "Alex",
    couponCode: "COMEBACK50",
    percentOff: 50,
    expiresLabel: "Sept 30",
    deployUrl: `${appUrl()}/dashboard/deploy`,
  });
  await writeFile(OUT, built.html, "utf8");
  console.log(`Wrote ${OUT}`);
  console.log(`Subject: ${built.subject}`);
  console.log(`Template tag: ${built.template}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

