/**
 * One-click MARKETING unsubscribe — tokenized, no-login.
 *
 * A signed (HMAC-SHA256) token identifies the user and carries a fixed PURPOSE
 * tag so it can never be repurposed as any other kind of link. The signing key is
 * the platform's existing `AUTH_SECRET` (the same secret lib/crypto-box.ts and
 * lib/auth.ts derive from) — no new unmanaged secret is introduced.
 *
 * `optOutMarketing` writes the EXACT signal `mayDeliverTo(userId,'product_news',
 * 'email')` reads: `User.notificationPrefs.product = false` (PRODUCT tier →
 * `mayDeliver` returns `prefs.product`). It also drops the address from the
 * newsletter list, mirroring `updateNotificationPrefs` so a marketing-consent
 * withdrawal is honoured everywhere marketing is addressed.
 */
import { createHmac, timingSafeEqual } from "node:crypto";
import { db } from "./db";
import { appUrl } from "./email-render";
import { normalizePrefs } from "./prefs";

/** Baked into the signature so a token minted here can only ever unsubscribe. */
const PURPOSE = "unsub-marketing";

function signingSecret(): string {
  const s = process.env.AUTH_SECRET;
  if (!s) throw new Error("AUTH_SECRET is not set — cannot sign unsubscribe tokens");
  return s;
}

function sign(userId: string): string {
  return createHmac("sha256", signingSecret()).update(`${PURPOSE}:${userId}`).digest("base64url");
}

/** `<userId>.<hmac>` — cuid userIds contain no dot, so the split is unambiguous. */
export function marketingUnsubToken(userId: string): string {
  return `${userId}.${sign(userId)}`;
}

/** Verify a token and return its userId, or null if malformed / bad signature. */
export function verifyMarketingUnsubToken(token: string | null | undefined): string | null {
  if (!token) return null;
  const dot = token.lastIndexOf(".");
  if (dot <= 0 || dot >= token.length - 1) return null;
  const userId = token.slice(0, dot);
  const sig = token.slice(dot + 1);
  let expected: string;
  try {
    expected = sign(userId);
  } catch {
    return null;
  }
  const a = Buffer.from(sig);
  const b = Buffer.from(expected);
  if (a.length !== b.length) return null;
  return timingSafeEqual(a, b) ? userId : null;
}

/** The absolute one-click unsubscribe URL for a user (used in the email + header). */
export function marketingUnsubUrl(userId: string): string {
  return `${appUrl()}/api/unsubscribe?token=${encodeURIComponent(marketingUnsubToken(userId))}`;
}

/**
 * Opt a user OUT of marketing / product-news. IDEMPOTENT.
 *
 * Returns true when the user exists (whether or not a change was needed), false
 * when the userId resolves to no account.
 */
export async function optOutMarketing(userId: string): Promise<boolean> {
  const user = await db.user.findUnique({
    where: { id: userId },
    select: { email: true, notificationPrefs: true },
  });
  if (!user) return false;

  const prefs = normalizePrefs(user.notificationPrefs);
  if (prefs.product) {
    // security stays pinned true (see NotificationPrefs.security).
    await db.user.update({
      where: { id: userId },
      data: { notificationPrefs: { email: prefs.email, product: false, security: true } },
    });
  }
  // Mirror updateNotificationPrefs: campaigns are addressed BY EMAIL, so also drop
  // the address from the product-news list. Best-effort — never block the opt-out.
  try {
    await db.newsletterSubscriber.deleteMany({ where: { email: user.email.toLowerCase() } });
  } catch {
    /* table optional on some environments */
  }
  return true;
}

import { NextRequest, NextResponse } from "next/server";
import { verifyMarketingUnsubToken, optOutMarketing } from "@/lib/marketing-unsub";

/**
 * Tokenized, NO-LOGIN marketing unsubscribe.
 *
 * The token (a signed `<userId>.<hmac>` from lib/marketing-unsub, purpose-tagged
 * so it can't be repurposed) is the whole authorization — the recipient proves
 * intent by clicking the link we mailed them. Opting out is idempotent and writes
 * the same signal `mayDeliverTo(userId,'product_news','email')` reads, so future
 * marketing sends to this user are suppressed centrally by `sendMail`.
 *
 *   GET  → flip the opt-out and render a friendly confirmation page.
 *   POST → RFC 8058 one-click (mailbox providers): opt out, 200, no body.
 *
 * Runs on the Node.js runtime because the verifier uses node:crypto.
 */
export const runtime = "nodejs";

async function applyOptOut(token: string | null): Promise<boolean> {
  const userId = verifyMarketingUnsubToken(token);
  if (!userId) return false;
  try {
    return await optOutMarketing(userId);
  } catch (e) {
    console.error("[unsubscribe] opt-out failed", e);
    return false;
  }
}

const PAGE = (bodyHtml: string) =>
  `<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Nxeon email preferences</title></head>
<body style="margin:0;background:#eef0f8;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:520px;margin:64px auto;padding:0 20px;">
    <div style="background:#fff;border-radius:16px;box-shadow:0 8px 30px rgba(40,25,90,0.10);padding:36px 34px;text-align:center;">
      ${bodyHtml}
    </div>
    <div style="text-align:center;margin-top:18px;color:#a7a4bd;font-size:12px;">NXEON CLOUD</div>
  </div>
</body></html>`;

const CONFIRM = PAGE(
  `<div style="font-size:13px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:#6f47f5;margin-bottom:12px;">Unsubscribed</div>
   <h1 style="margin:0 0 12px;font-size:22px;color:#1c1638;">You're unsubscribed from marketing emails</h1>
   <p style="margin:0;font-size:15px;line-height:1.6;color:#4a4763;">You won't receive Nxeon marketing or product-news emails anymore. You'll still get essential account emails — things like receipts, security alerts and anything about a server you own.</p>
   <p style="margin:16px 0 0;font-size:13px;color:#8a86a3;">Changed your mind? You can re-enable product updates anytime in your <a href="/dashboard/settings" style="color:#6f47f5;">notification settings</a>.</p>`,
);

const INVALID = PAGE(
  `<h1 style="margin:0 0 12px;font-size:22px;color:#1c1638;">This link isn't valid</h1>
   <p style="margin:0;font-size:15px;line-height:1.6;color:#4a4763;">This unsubscribe link looks incomplete or has expired. You can manage all your email preferences from your <a href="/dashboard/settings" style="color:#6f47f5;">notification settings</a>.</p>`,
);

export async function GET(req: NextRequest) {
  const ok = await applyOptOut(req.nextUrl.searchParams.get("token"));
  return new NextResponse(ok ? CONFIRM : INVALID, {
    status: ok ? 200 : 400,
    headers: { "content-type": "text/html; charset=utf-8" },
  });
}

export async function POST(req: NextRequest) {
  // RFC 8058 one-click. Providers POST here with body `List-Unsubscribe=One-Click`.
  // Process idempotently and always answer 200 with no body — never leak whether a
  // token was valid, and never make a provider retry.
  await applyOptOut(req.nextUrl.searchParams.get("token"));
  return new NextResponse(null, { status: 200 });
}

