/**
 * Preview the deploy WIN-BACK email — renders `emails.deployWinback(...)` with
 * sample data and writes the full HTML to disk so the owner can open it.
 *
 * Run:  npx tsx scripts/preview-deploy-winback.ts
 * Out:  /opt/nxeon-wt-winback/winback-preview.html
 *
 * Imports ONLY the pure template builder (lib/email-templates) — `deployWinback`
 * is string composition with no DB access, so this touches no database and sends
 * no email. `@/` path alias resolves under tsx (same as the other repo scripts).
 *
 * LOGO: the real template/shell keeps the HOSTED logo URL (data URIs get stripped
 * by some clients). This is a PREVIEW-ONLY convenience — local preview panes block
 * remote images, so AFTER building we swap the hosted `<url>/logo.png` src for a
 * base64 `data:` URI just in the written file. The production template is untouched.
 */
import { readFile, writeFile } from "node:fs/promises";
import { emails } from "../lib/email-templates";
import { appUrl } from "../lib/email-render";

const OUT = "/opt/nxeon-wt-winback/winback-preview.html";
const LOGO = "/opt/nxeon-wt-winback/public/logo.png";

async function main() {
  const built = emails.deployWinback({
    name: "Alex",
    couponCode: "COMEBACK50",
    percentOff: 50,
    expiresLabel: "Sept 30",
    deployUrl: `${appUrl()}/dashboard/deploy`,
    // Sample only — the real per-recipient signed URL is built by the worker sweep.
    unsubscribeUrl: `${appUrl()}/api/unsubscribe?token=SAMPLE_TOKEN`,
  });

  // Preview-only: inline the logo so it renders in a local, remote-image-blocked pane.
  let html = built.html;
  try {
    const b64 = (await readFile(LOGO)).toString("base64");
    const dataUri = `data:image/png;base64,${b64}`;
    const hostedSrc = `${appUrl()}/logo.png`;
    html = html.split(hostedSrc).join(dataUri);
  } catch (e) {
    console.warn(`(logo not inlined — ${String((e as Error)?.message ?? e)})`);
  }

  await writeFile(OUT, html, "utf8");
  console.log(`Wrote ${OUT}`);
  console.log(`Subject: ${built.subject}`);
  console.log(`Template tag: ${built.template}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

