"use client";

import { SettingsForm, TextField, ToggleField } from "./fields";

/**
 * Deploy win-back re-engagement controls. Saves through the shared `saveSettings`
 * action (section "winback") exactly like every other panel — bool + two ints,
 * validated + cross-field-checked server-side in lib/actions-settings.ts.
 */
export function WinbackPanel({ v }: { v: Record<string, string> }) {
  return (
    <SettingsForm
      section="winback"
      title="Deploy win-back emails"
      desc="Automatically email signed-in users who started the deploy wizard and left, offering a first-month discount. Off by default — nothing sends until you enable it."
    >
      <ToggleField
        label="Enable win-back emails"
        name="deploy_winback_enabled"
        defaultChecked={v.deploy_winback_enabled === "true"}
        hint="When on, the worker emails eligible abandoners once each (marketing kind, opt-out honoured). Create the COMEBACK50 coupon before turning this on."
      />
      <TextField
        label="Wait before emailing (minutes)"
        name="deploy_winback_delay_minutes"
        type="number"
        min={1}
        defaultValue={v.deploy_winback_delay_minutes}
        hint="How long after someone's last wizard step to wait before emailing — so we never interrupt an active setup. Default 30."
      />
      <TextField
        label="How far back to look (days)"
        name="deploy_winback_max_age_days"
        type="number"
        min={1}
        defaultValue={v.deploy_winback_max_age_days}
        hint="Only email people whose last step was within this many days, so the nudge stays timely. Must be greater than the wait above. Default 30."
      />
    </SettingsForm>
  );
}

